import urllib.request
from html.parser import HTMLParser
class P(HTMLParser):
 def handle_data(self,d):
  if d.strip(): self.lines.append(d.strip())
for u in ['https://yjs.qfnu.edu.cn/info/1043/5273.htm','https://soe.ruc.edu.cn/info/1082/3889.htm']:
 print('URL',u)
 try:
  req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'})
  s=urllib.request.urlopen(req,timeout=25).read().decode('utf-8',errors='replace')
  p=P();p.lines=[];p.feed(s)
  text='\\n'.join(p.lines)
  start=text.find('一、工作原则') if 'qfnu' in u else text.find('三、申请条件')
  print(text[start:start+6500])
 except Exception as e: print(type(e).__name__,str(e))
PY"

